import{_ as e,c as i,o as r,ag as t}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"隱私選項","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1794112334000}'),s={name:"zh-TW/guide/privacy-choices.md"};function o(c,a,l,h,n,p){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="隱私選項" tabindex="-1">隱私選項 <a class="header-anchor" href="#隱私選項" aria-label="Permalink to &quot;隱私選項&quot;">​</a></h1><p>本頁說明如何向 Nicasa 提交隱私請求，以及你可以預期的處理方式。</p><h2 id="適用情況" tabindex="-1">適用情況 <a class="header-anchor" href="#適用情況" aria-label="Permalink to &quot;適用情況&quot;">​</a></h2><p>你可以使用本頁請求查閱個人資料、請求刪除、請求資料可攜，或選擇退出某些資料使用（例如在適用情況下的「請勿出售」請求）。</p><p>說明：Nicasa 目前不蒐集也不儲存個人資料（見隱私權政策）。如果你確信我們持有關於你的個人資料，請提交請求，我們會展開調查。</p><h2 id="如何提交請求" tabindex="-1">如何提交請求 <a class="header-anchor" href="#如何提交請求" aria-label="Permalink to &quot;如何提交請求&quot;">​</a></h2><p>提交請求時請提供以下資訊，以便我們有效率地處理：</p><ul><li>你的姓名</li><li>聯絡電子郵件</li><li>請求說明（查閱、刪除、可攜或退出）</li><li>任何有助於我們定位記錄的資訊（例如支援工單編號）</li></ul><p>請將請求寄送至以下任一管道：</p><ul><li>電子郵件：nicasa@w3cub.com</li><li>提交隱私 issue：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="回應時間" tabindex="-1">回應時間 <a class="header-anchor" href="#回應時間" aria-label="Permalink to &quot;回應時間&quot;">​</a></h2><p>我們力求在 30 天內確認並回應有效請求。如需要更多時間，我們會通知你並提供預計時程。</p><h2 id="如果我們未持有個人資料" tabindex="-1">如果我們未持有個人資料 <a class="header-anchor" href="#如果我們未持有個人資料" aria-label="Permalink to &quot;如果我們未持有個人資料&quot;">​</a></h2><p>由於 Nicasa 的設計是在本機處理圖片而不蒐集使用者資料，許多請求會以「未持有任何個人資料」的確認結案。如果你能提供個人資料曾被蒐集的證據，我們會展開調查並採取適當措施。</p><h2 id="請勿出售-選擇退出" tabindex="-1">請勿出售 / 選擇退出 <a class="header-anchor" href="#請勿出售-選擇退出" aria-label="Permalink to &quot;請勿出售 / 選擇退出&quot;">​</a></h2><p>如果你正在行使某一司法管轄區的權利（例如依據 CCPA/CPRA）要求退出資料出售，並且你確信我們曾出售你的個人資料，請在請求中說明具體情況。如果我們並未出售個人資料，會在回覆中予以確認。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>如對本流程有疑問，請聯絡 <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a>，或在 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a> 提交 issue。</p>',18)])])}const b=e(s,[["render",o]]);export{d as __pageData,b as default};
